{
  "bioavailability_prediction": "high",
  "confidence": "high",
  "revision_action": "keep",
  "supportive_card_ids": [
    "C19","C31","C04","C06","C15","C20","C23","C24","C17","C28",
    "C01","C05","C10","C13","C18","C22","C30","C03","C09","C11",
    "C14","C07","C12","C16","C02","C08","C29","C21","C26"
  ],
  "contradictory_card_ids": [],
  "prediction_basis_card_ids": [
    "C19","C31","C04","C06","C15","C20","C23","C24","C17","C28",
    "C01","C05","C10","C13","C18","C22","C30"
  ],
  "claims": [
    {
      "claim": "Emtricitabine, the closest supplied analog, has measured absolute oral bioavailability of 92% fasted, 93% in multiple reports, 75% as an oral solution, 58-97% overall, 73±6% in monkeys, and 90±8% in rats, all far above 20%.",
      "card_ids": ["C19","C31","C01","C05","C10","C13","C18","C22","C30"]
    },
    {
      "claim": "Lamivudine, another pyrimidine dideoxynucleoside, has absolute F of 87% (solution), 69±9%, 81±19%, 68.6±11%, 93±15%, and 86±17% across doses and formulations, all above 20%.",
      "card_ids": ["C04","C06","C15","C20","C23","C24"]
    },
    {
      "claim": "Zalcitabine, a pyrimidine dideoxynucleoside with a dideoxy sugar, has absolute F of 80% (54-127%) in humans and 30% in fasted mice, both above 20%.",
      "card_ids": ["C17","C28"]
    },
    {
      "claim": "New L3 lamivudine oral exposure records show rapid absorption (median Tmax ~0.75-1.26 h) and measurable Cmax after oral dosing, consistent with the high absolute F values recorded for lamivudine.",
      "card_ids": ["C33","C36","C42","C32","C38","C39","C43","C34","C35","C40","C41"]
    },
    {
      "claim": "No supplied record provides affirmative threshold-relevant evidence for F<20% for the query or its close pyrimidine dideoxynucleoside analogs; didanosine's variable/low average is tied to its buffering requirements and is not transferable to the pyrimidine query.",
      "card_ids": ["C03","C09","C11","C14","C25","C27","C07","C12","C16"]
    },
    {
      "claim": "Theophylline records show high oral bioavailability in dogs and humans, consistent with but not decisive for the query.",
      "card_ids": ["C02","C08","C29"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "oral_auc_cmax_exposure",
      "applicability": "moderate",
      "direction": "supportive",
      "decision_effect": "no_change",
      "card_ids": ["C32","C33","C34","C35","C36","C38","C39","C40","C41","C42","C43"]
    },
    {
      "family": "oral_auc_cmax_exposure",
      "applicability": "not_applicable",
      "direction": "neutral_or_unclear",
      "decision_effect": "no_change",
      "card_ids": ["C37"]
    }
  ],
  "evidence_gaps": [
    "No direct stavudine absolute-bioavailability record is present; prediction relies on structural transfer from closely related pyrimidine dideoxynucleosides.",
    "No query-specific IV comparison, AUC, Cmax, dose, or formulation data are supplied.",
    "Food effects and metabolic/clearance contributions for the query are not directly measured in the cited records.",
    "L3 records are lamivudine exposure parameters, not stavudine F measurements; transfer is indirect.",
    "Formulation sensitivity seen in lamivudine and didanosine records means the exact F for the query could vary, but the available evidence still supports F>=20%."
  ],
  "decision_summary": "High: stavudine is a thymine dideoxynucleoside closely related to emtricitabine, lamivudine, and zalcitabine, all with measured absolute oral bioavailability well above 20%; new L3 lamivudine exposure records show rapid oral absorption and measurable Cmax, consistent with high F; no transferable affirmative evidence supports F<20%."
}

